import json,shutil
from colors import colorize
from pathlib import Path
R=Path.cwd();O=R/'outputs/experiment'
def read(p):return json.loads(p.read_text())
data=dict(manifest=read(O/'manifest.json'),labels={c:read(O/'labels'/f'{c}.json') for c in 'ABCD'},references={c:[read((O/'adjudication'/f'{c}_{t:02d}.json') if (O/'adjudication'/f'{c}_{t:02d}.json').exists() else (O/'verification'/f'{c}_{t:02d}.json')) for t in range(0,20,4)] for c in 'ABCD'},predictions=[read(p) for p in sorted((O/'predictions').glob('*.json'))],scores=read(O/'scores.json'))
pose_ids={'A':'01-standing','B':'02-takedown','C':'03-ground','D':'04-finish'}
data['poses']={c:read(R/'outputs/pose'/f'{name}__rtmw.json') for c,name in pose_ids.items()}
data['labels']={c:[colorize(x) for x in v] for c,v in data['labels'].items()}
data['references']={c:[colorize(x) for x in v] for c,v in data['references'].items()}
(O/'reviewed_labels.json').write_text(json.dumps(data['references'],indent=2))
for p in data['predictions']:
 for field in ['phase_probs','next_action_probs']:
  total=sum(p[field].values());p[field]={k:v/total for k,v in p[field].items()}
 original=read(O/'labels'/f"{p['clip']}.json")[0]
 temp=dict(original,forecast=p.get('forecast',''),evidence=p.get('evidence',[]),limits=p.get('limits',[]))
 colored=colorize(temp)
 for k in ['forecast','evidence','limits']:p[k]=colored[k]
html='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MMA — annotation laboratory</title><style>
:root{color-scheme:dark;--bg:#111411;--panel:#1a201b;--ink:#e9f0e8;--muted:#a7b3a8;--accent:#c6ee8b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,sans-serif}main{max-width:1440px;margin:auto;padding:32px}header{display:flex;justify-content:space-between;gap:20px;align-items:center}h1{font-size:clamp(28px,4vw,48px);font-weight:550;letter-spacing:-1.6px;margin:0}h2{font-size:20px;margin:0 0 12px}p{margin:9px 0;color:var(--muted)}.eyebrow{color:var(--accent);font-size:12px;letter-spacing:2px}.notice{border-left:3px solid var(--accent);padding:12px 18px;margin:20px 0;background:var(--panel)}.grid{display:grid;grid-template-columns:1.1fr 1fr;gap:22px}.card{background:var(--panel);border:1px solid #303a31;border-radius:14px;padding:20px}.videoWrap{position:relative}.videoWrap canvas{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}video{width:100%;aspect-ratio:16/9;background:#000;border-radius:9px}button,select{font:inherit;background:#273329;border:1px solid #52624c;border-radius:7px;color:var(--ink);padding:8px 12px;cursor:pointer}button.active{background:var(--accent);color:#13210d}.controls{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0}label{color:var(--muted)}.prob{display:grid;grid-template-columns:155px 1fr 48px;align-items:center;gap:8px;font-size:13px;margin:8px 0}.track{height:8px;background:#343f35;border-radius:4px;overflow:hidden}.fill{height:100%;background:var(--accent)}.small{font-size:12px;color:var(--muted)}.event{padding:12px 0;border-top:1px solid #364136}.pill{color:var(--accent);font-size:12px;padding-right:12px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;border-bottom:1px solid #344035;padding:10px 8px}th{color:var(--muted);font-weight:500}details{margin-top:16px}summary{cursor:pointer;color:var(--accent)}a{color:var(--accent)}.below{margin-top:22px}.positive{color:var(--accent)}pre{white-space:pre-wrap;font-size:12px}#reference{display:none}@media(max-width:850px){main{padding:18px}.grid{grid-template-columns:1fr}header{display:block}.prob{grid-template-columns:135px 1fr 45px}}
</style></head><body><main><header><div><div class="eyebrow">80 SECONDS · FROZEN MODELS · CAUSAL INPUTS</div><h1>The MMA annotation laboratory</h1></div><a href="../review.html">Original model comparison ↗</a></header><div class="notice">GPT‑6.1 Sol annotations and predictions, with independent dense-frame review. Reference labels are model-reviewed observations, not expert ground truth. Four selected clips cannot establish general prediction accuracy.</div><div class="controls" id="clips"></div><div class="controls"><label>Prediction cutoff <select id="cutoff"><option>4</option><option>8</option><option>12</option><option>16</option></select> seconds</label><label>Input <select id="condition"><option value="coarse_history">Coarse phase history</option><option value="rich_recent">Rich last interval</option><option value="rich_history">Rich entire prefix</option><option value="reviewed_history" selected>Dense reviewed prefix</option><option value="reviewed_pose_history">Reviewed prefix + RTMW detail</option></select></label><label>Run <select id="repeat"><option>1</option><option>2</option></select></label></div><div class="grid"><section class="card"><h2 id="caseTitle"></h2><div class="videoWrap"><video id="video" muted playsinline preload="metadata"></video><canvas id="poseCanvas" width="960" height="540"></canvas></div><label class="small"><input type="checkbox" id="poseToggle" checked> RTMW face, hands and feet estimates (12 Hz; ownership unverified)</label><div class="controls"><button id="past">Play observed prefix</button><button id="reveal">Reveal continuation + reference</button><button id="pause">Pause</button></div><p id="videoState" class="small"></p><h2 style="margin-top:22px">Annotations available at cutoff</h2><div id="history"></div><details><summary>Annotation record with clothing colors</summary><pre id="json"></pre></details></section><section class="card"><h2>Frozen forecast</h2><p id="forecast"></p><h3>Phase four seconds later</h3><div id="phase"></div><h3>First committed action</h3><div id="action"></div><h3>Any occurrence in next four seconds</h3><div id="events"></div><details open><summary>Evidence and limitations</summary><div id="reason"></div></details><div id="reference" class="below"><h2>Independent visual reference</h2><p id="referenceText"></p><div id="referenceEvents"></div></div></section></div><section class="card below"><h2>Matched experiment results</h2><p>Lower Brier is better. Phase/action Brier uses sum of squared class errors; event Brier is binary squared error. Ambiguous reference cells are excluded. Runs share the same cases and are not extra samples.</p><div style="overflow-x:auto"><table id="scores"></table></div><p class="small">Persistence uses the preceding causal label. Cross-bout prevalence excludes the source bout, grouping clips C/D together. These are descriptive controls, not deployment estimates.</p></section><section class="card below"><h2>Audit and interpretation</h2><p>8-Hz causal labeling → text-only forecasts → independent 16-Hz labeling → disputed intervals revisited. Predictions receive no images or future labels. Dense reviewed-prefix forecasts are a separate retrospective input experiment, still limited to past intervals.</p><a href="rich-annotated-A.mp4">Annotated striking</a> · <a href="rich-annotated-B.mp4">Annotated takedown</a> · <a href="rich-annotated-C.mp4">Annotated ground</a> · <a href="rich-annotated-D.mp4">Annotated clinch</a> · <a href="annotation-preview.mp4">First-pass example</a> · <a href="contact-evidence-example.jpg">Contact evidence strip</a> · <a href="report.txt">Findings and next goals</a> · <a href="protocol.txt">Protocol</a> · <a href="case_scores.csv">Every scored case</a> · <a href="reviewed_labels.json">Reviewed annotations</a> · <a href="scores.json">Metrics JSON</a><p class="small">Full raw prompts, outputs, model settings and input hashes are included in the downloadable experiment archive.</p></section></main><script>
const DATA=__DATA__;let clip='A',revealed=false,playEnd=4;const $=x=>document.getElementById(x),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const nice=x=>x.replaceAll('_',' ');function bars(id,p){$(id).innerHTML=Object.entries(p).map(([k,v])=>`<div class="prob"><span>${esc(nice(k))}</span><div class="track"><div class="fill" style="width:${v*100}%"></div></div><span>${Math.round(v*100)}%</span></div>`).join('')}function eventHtml(e){return `<div class="event"><button onclick="seekEvent(${e.time_start},${e.time_end})" style="font-size:12px;padding:3px 7px;margin-right:8px">Inspect ${e.time_start.toFixed(2)}s</button><span class="pill">${e.time_start.toFixed(2)}–${e.time_end.toFixed(2)}s · ${esc(e.actor)}</span><span class="pill">${esc(e.contact)} · ${esc(e.certainty)}</span><div>${esc(e.action)}</div><p class="small">${esc(e.evidence)}</p></div>`}function render(){let t=+$('cutoff').value,k=$('condition').value,r=+$('repeat').value;let p=DATA.predictions.find(x=>x.clip===clip&&x.cutoff===t&&x.condition===k&&x.repeat===r);if(!p){$('repeat').value=1;p=DATA.predictions.find(x=>x.clip===clip&&x.cutoff===t&&x.condition===k&&x.repeat===1)}if(!p){$('condition').value='rich_history';return render()}revealed=false;$('reference').style.display='none';playEnd=t;$('video').pause();let src=`clips/${clip}.mp4`;if(!$('video').src.endsWith('/'+src))$('video').src=src;$('video').currentTime=t;$('caseTitle').textContent=`Clip ${clip} · predict ${t}–${t+4}s`;$('videoState').textContent='Continuation withheld until reveal.';$('forecast').textContent=p.forecast;bars('phase',p.phase_probs);bars('action',p.next_action_probs);bars('events',p.event_probs);$('reason').innerHTML=[...p.evidence,...p.limits].map(x=>`<p class="small">${esc(x)}</p>`).join('');let hist=(k==='reviewed_history'?DATA.references[clip]:DATA.labels[clip]).filter(x=>x.end<=t);if(k==='rich_recent')hist=hist.slice(-1);if(k==='coarse_history')hist=hist.map(x=>Object.fromEntries(['start','end','start_phase','end_phase','visibility'].map(key=>[key,x[key]])));$('json').textContent=JSON.stringify(hist,null,2);$('history').innerHTML=hist.map(x=>`<details ${x.end===t?'open':''}><summary>${x.start}–${x.end}s · ${esc(x.end_phase)}</summary><p>${esc(x.position||'Phase and visibility only.')}</p>${(x.events||[]).map(eventHtml).join('')}<p class="small">${esc((x.uncertainties||[]).join(' '))}</p></details>`).join('');document.querySelectorAll('[data-clip]').forEach(b=>b.classList.toggle('active',b.dataset.clip===clip))}
function seekEvent(a,b){$('video').pause();$('video').currentTime=a;playEnd=Math.min(revealed?+$('cutoff').value+4:+$('cutoff').value,b+.15)}
function drawPose(){const cv=$('poseCanvas'),ctx=cv.getContext('2d');ctx.clearRect(0,0,960,540);if(!$('poseToggle').checked)return;let arr=DATA.poses[clip].frames,f=arr[Math.min(arr.length-1,Math.floor($('video').currentTime*12))];if(!f)return;const edges=[[5,6],[5,7],[7,9],[6,8],[8,10],[5,11],[6,12],[11,12],[11,13],[13,15],[12,14],[14,16],[15,17],[17,18],[15,19],[16,20],[20,21],[16,22]];for(let root of [91,112])for(let finger=0;finger<5;finger++){let a=root+1+4*finger;edges.push([root,a]);for(let j=a;j<a+3;j++)edges.push([j,j+1])}for(let [a,b] of [[23,40],[40,45],[45,50],[50,54],[54,59],[59,65],[65,71],[71,83],[83,91]])for(let j=a;j<b-1;j++)edges.push([j,j+1]);for(let person of f.people){let k=person.keypoints;const valid=p=>p[2]>=.3&&p[0]>=0&&p[0]<960&&p[1]>=0&&p[1]<540;ctx.strokeStyle='#c6ee8b';ctx.fillStyle='#c6ee8b';for(let [a,b] of edges)if(valid(k[a])&&valid(k[b])){ctx.lineWidth=a<23?1.5:0.7;ctx.beginPath();ctx.moveTo(k[a][0],k[a][1]);ctx.lineTo(k[b][0],k[b][1]);ctx.stroke()}k.forEach((p,j)=>{if(valid(p)){ctx.beginPath();ctx.arc(p[0],p[1],j<23?2:1,0,Math.PI*2);ctx.fill()}});}}$('poseToggle').onchange=drawPose;$('video').addEventListener('seeked',drawPose);$('video').addEventListener('loadeddata',drawPose);function animatePose(){drawPose();requestAnimationFrame(animatePose)}requestAnimationFrame(animatePose);
$('clips').innerHTML='ABCD'.split('').map(c=>`<button data-clip="${c}">Clip ${c}</button>`).join('');document.querySelectorAll('[data-clip]').forEach(b=>b.onclick=()=>{clip=b.dataset.clip;render()});['cutoff','condition','repeat'].forEach(x=>$(x).onchange=render);$('past').onclick=()=>{playEnd=+$('cutoff').value;$('video').currentTime=0;$('video').play()};$('pause').onclick=()=>$('video').pause();$('reveal').onclick=()=>{revealed=true;let t=+$('cutoff').value;playEnd=t+4;$('video').currentTime=t;$('video').play();$('videoState').textContent='Continuation revealed. Predictions above were frozen before scoring.';let ref=DATA.references[clip].find(x=>x.start===t);$('reference').style.display='block';$('referenceText').textContent=`End phase: ${ref.end_phase}. First action: ${nice(ref.first_action||'unclear')}. Events: ${Object.entries(ref.event_flags).map(([k,v])=>nice(k)+' = '+v).join('; ')}.`;$('referenceEvents').innerHTML=ref.events.map(eventHtml).join('')};$('video').ontimeupdate=()=>{if($('video').currentTime>=playEnd){$('video').pause();if($('video').currentTime>playEnd+.2)$('video').currentTime=playEnd}};let ss=DATA.scores.filter(x=>['phase','first_action','all_events'].includes(x.target));$('scores').innerHTML='<thead><tr><th>Input</th><th>Run</th><th>Target</th><th>Scored</th><th>Top-1 / binary accuracy</th><th>Brier</th></tr></thead><tbody>'+ss.map(x=>`<tr><td>${esc(nice(x.condition))}</td><td>${x.repeat}</td><td>${esc(nice(x.target))}</td><td>${x.n}/${x.possible}</td><td>${x.accuracy==null?'—':(100*x.accuracy).toFixed(1)+'%'}</td><td>${x.brier==null?'—':x.brier.toFixed(3)}</td></tr>`).join('')+'</tbody>';render();
</script></body></html>'''
(O/'index.html').write_text(html.replace('__DATA__',json.dumps(data).replace('</','<\\/')))
